import re, glob

tex_cited = set()
for f in glob.glob('*.tex'):
    with open(f) as fh:
        text = fh.read()
    for m in re.finditer(r'\\cite[tp]?\{([^}]+)\}', text):
        for key in m.group(1).split(','):
            tex_cited.add(key.strip())
    for m in re.finditer(r'\\citet\{([^}]+)\}', text):
        for key in m.group(1).split(','):
            tex_cited.add(key.strip())

with open('references.bib') as fh:
    bib_text = fh.read()
bib_keys = set(re.findall(r'@\w+\{(\S+),', bib_text))

orphan_bib = bib_keys - tex_cited
missing_bib = tex_cited - bib_keys

print(f'Cited: {len(tex_cited)}, Bib: {len(bib_keys)}')
print(f'Orphan bib (not cited): {len(orphan_bib)}')
for k in sorted(orphan_bib): print(f'  {k}')
print(f'Missing bib (cited but no entry): {len(missing_bib)}')
for k in sorted(missing_bib): print(f'  {k}')
